# =======================================================================
# АВТОГЕНОВАНИЙ МОНОЛІТНИЙ x86_64 АСЕМБЛЕРНИЙ АЛГОРИТМ (GAS / .intel_syntax)
# МАТРИЦЯ АРХЕТИПІВ ВСІХ БУКВ ТА РОЗГОРНУТИЙ ДИСПЕТЧЕР РЕЗОНАНСУ
# Суворо No-Mul граф: жодної інструкції imul/mul/fmul у всьому моноліті
# Множення на 0x9E3779B9 (хеш Кнута) реалізовано зсув-додавальним ланцюгом
# =======================================================================
.intel_syntax noprefix

.globl archetype_unrolled_dispatch
.globl archetype_resonance_eval
.text

archetype_resonance_eval:
    # Вхід: rdi = char codepoint, rsi = target archetype (0..11)
    # Вихід: eax = (вага+1) у 16.16 fixed-point: 0x0000 / 0x10000 / 0x20000
    push rbx
    push r12
    push r13
    mov eax, edi
    # No-Mul множення на 0x9E3779B9: 20 встановлених бітів константи
    mov ecx, eax
    xor edx, edx
    add edx, ecx
    shl ecx, 3
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 2
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 3
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 2
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 2
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 4
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 1
    add edx, ecx
    shl ecx, 3
    add edx, ecx
    mov eax, edx
    shr eax, 28
    xor edx, edx
    mov ecx, 12
    div ecx
    mov r12d, edx
    cmp esi, 12
    jae .out_of_bounds
    lea rbx, [rip + ARCHETYPE_WEIGHT_TABLE]
    lea r13, [r12 + r12*2]
    shl r13, 2
    add r13, rsi
    movsx eax, byte ptr [rbx + r13]
    shl eax, 16
    add eax, 0x00010000
    jmp .done
.out_of_bounds:
    xor eax, eax
.done:
    pop r13
    pop r12
    pop rbx
    ret

